def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for r, row in enumerate(grid):
        end = w - 1
        while end >= 0 and row[end] == bg:
            end -= 1
        if end < 0:
            continue

        color = row[end]
        start = end
        while start >= 0 and row[start] == color:
            start -= 1

        if end < w - 1 and end - start >= 5:
            for c in range(end + 1, w):
                out[r][c] = 1

    return out
